const escapeHTML=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const header=document.querySelector('#header'),menu=document.querySelector('.menu-toggle');
menu.addEventListener('click',()=>{const open=header.classList.toggle('menu-open');menu.setAttribute('aria-expanded',open);menu.setAttribute('aria-label',open?'Zamknij menu':'Otwórz menu')});
function closeMenu(){header.classList.remove('menu-open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Otwórz menu')}
document.querySelectorAll('#nav a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&header.classList.contains('menu-open')){closeMenu();menu.focus()}});
const grid=document.querySelector('#projectGrid');
if(grid){
 const projects=window.BEPLAN_PROJECTS;let filter='Wszystkie',activeProject=null,imageIndex=0,opener=null;
 function renderProjects(){const list=projects.filter(p=>filter==='Wszystkie'||p.category===filter);grid.innerHTML=list.map(p=>`<button class="project-card" data-project="${p.id}" aria-label="Zobacz projekt ${escapeHTML(p.title)}"><div class="project-picture"><img src="${p.images[0]}" alt="${escapeHTML(p.title)} — ${escapeHTML(p.location)}" loading="lazy" width="1400" height="960"></div><div class="project-meta"><div><h3>${escapeHTML(p.title)}</h3><p>${escapeHTML(p.location)}</p></div><span>${p.area} <b aria-hidden="true">↗</b></span></div></button>`).join('');document.querySelector('.project-count').textContent=list.length+' projektów';}
 renderProjects();document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(el=>{el.classList.toggle('active',el===b);el.setAttribute('aria-pressed',el===b)});renderProjects()}));
 const dialog=document.querySelector('#projectDialog');
grid.addEventListener('click',e=>{const card=e.target.closest('[data-project]');if(card){opener=card;location.hash='projekt/'+card.dataset.project}});
function setImage(index){imageIndex=(index+activeProject.images.length)%activeProject.images.length;const image=document.querySelector('#galleryImage');image.src=activeProject.images[imageIndex];image.alt=`${activeProject.title} — zdjęcie ${imageIndex+1} z ${activeProject.images.length}`;document.querySelector('#imageCounter').textContent=`${String(imageIndex+1).padStart(2,'0')} / ${String(activeProject.images.length).padStart(2,'0')}`;document.querySelectorAll('[data-image]').forEach(b=>{const active=Number(b.dataset.image)===imageIndex;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)});}
function openProject(id){const project=projects.find(p=>p.id===id);if(!project)return;activeProject=project;document.querySelector('#projectTitle').textContent=project.title;document.querySelector('#projectCategory').textContent=project.category.toUpperCase();document.querySelector('#projectLocation').textContent=project.location;document.querySelector('#projectArea').textContent=project.area;document.querySelector('#projectDescription').textContent=project.description;document.querySelector('#thumbnails').innerHTML=project.images.map((src,i)=>`<button data-image="${i}" aria-label="Zdjęcie ${i+1}" aria-pressed="false"><img src="${src}" alt="" loading="lazy"></button>`).join('');setImage(0);if(!dialog.open)dialog.showModal();dialog.scrollTop=0;}
function closeProject(){if(dialog.open)dialog.close();if(location.hash.startsWith('#projekt/'))history.replaceState(null,'','#projekty');opener?.focus({preventScroll:true});}
document.querySelector('#closeProject').addEventListener('click',closeProject);
dialog.addEventListener('cancel',e=>{e.preventDefault();closeProject()});
dialog.addEventListener('click',e=>{if(e.target===dialog){const rect=dialog.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeProject()}});
document.querySelector('#thumbnails').addEventListener('click',e=>{const b=e.target.closest('[data-image]');if(b)setImage(Number(b.dataset.image))});
document.querySelector('#prevImage').addEventListener('click',()=>setImage(imageIndex-1));document.querySelector('#nextImage').addEventListener('click',()=>setImage(imageIndex+1));
dialog.addEventListener('keydown',e=>{if(e.key==='ArrowRight'){e.preventDefault();setImage(imageIndex+1)}if(e.key==='ArrowLeft'){e.preventDefault();setImage(imageIndex-1)}});
function changeProject(step){const i=projects.indexOf(activeProject);location.hash='projekt/'+projects[(i+step+projects.length)%projects.length].id;}
document.querySelector('#previousProject').addEventListener('click',()=>changeProject(-1));document.querySelector('#nextProject').addEventListener('click',()=>changeProject(1));

function route(){if(location.hash.startsWith('#projekt/'))openProject(decodeURIComponent(location.hash.slice(9)));else if(dialog.open)dialog.close();}
window.addEventListener('hashchange',route);route();

}
const form=document.querySelector('#contactForm');if(form)form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const data=new FormData(form);const body=['Imię i nazwisko: '+data.get('name'),'Firma: '+data.get('company'),'E-mail: '+data.get('email'),'Telefon: '+data.get('phone'),'Rodzaj inwestycji: '+data.get('type'),'','Wiadomość:',data.get('message')].join('\n');location.href='mailto:i.molnar@beplan.pl?subject='+encodeURIComponent('Zapytanie o projekt — '+data.get('type'))+'&body='+encodeURIComponent(body);document.querySelector('#formStatus').textContent='Wiadomość jest przygotowana do wysłania w Twoim programie pocztowym. Jeśli nie otworzył się automatycznie, napisz na i.molnar@beplan.pl.';});
if('IntersectionObserver' in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target)}}),{threshold:.06});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));document.body.classList.add('motion-ready');}
